import java.util.*;
import java.io.*;

public class Main {
    static int N, Q;
    static long K;
    static long[] A, B, C;
    static LongMap mapB, mapC;
    static boolean[] active;
    static int[] leftBound, rightBound;
    static int[] D;
    static long[] ansArr;

    public static void main(String[] args) throws IOException {
        FastScanner sc = new FastScanner();
        N = sc.nextInt();
        Q = sc.nextInt();
        K = sc.nextLong();

        A = new long[N + 1];
        B = new long[N + 1];
        C = new long[N + 1];

        for (int i = 1; i <= N; i++) {
            A[i] = sc.nextLong();
            B[i] = A[i] + i;
            C[i] = A[i] - i;
        }

        D = new int[Q + 1];
        boolean[] deleted = new boolean[N + 1];
        for (int t = 1; t <= Q; t++) {
            D[t] = sc.nextInt();
            deleted[D[t]] = true;
        }

        buildMaps();

        active = new boolean[N + 1];
        for (int i = 1; i <= N; i++) {
            active[i] = !deleted[i];
        }

        leftBound = new int[N + 1];
        rightBound = new int[N + 1];
        ansArr = new long[Q + 1];

        long ans = 0;

        // Initial state after all Q deletions
        for (int i = 1; i <= N; ) {
            if (!active[i]) {
                i++;
                continue;
            }
            int L = i;
            while (i <= N && active[i]) i++;
            int R = i - 1;

            leftBound[R] = L;
            rightBound[L] = R;

            for (int x = L; x < R; x++) {
                ans += countRight(x, x + 1, R);
            }
        }

        ansArr[Q] = ans;

        // Process insertions backwards
        for (int t = Q; t >= 1; t--) {
            int d = D[t];

            boolean hasLeft = d > 1 && active[d - 1];
            boolean hasRight = d < N && active[d + 1];

            int L = d, R = d;
            if (hasLeft) L = leftBound[d - 1];
            if (hasRight) R = rightBound[d + 1];

            long added = 0;

            if (hasLeft) {
                added += countLeft(d, L, d - 1);
            }
            if (hasRight) {
                added += countRight(d, d + 1, R);
            }

            if (hasLeft && hasRight) {
                int lenL = d - L;
                int lenR = R - d;

                if (lenL <= lenR) {
                    for (int i = L; i <= d - 1; i++) {
                        added += countRight(i, d + 1, R);
                    }
                } else {
                    for (int j = d + 1; j <= R; j++) {
                        added += countLeft(j, L, d - 1);
                    }
                }
            }

            ans += added;
            ansArr[t - 1] = ans;

            active[d] = true;
            leftBound[R] = L;
            rightBound[L] = R;
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i <= Q; i++) {
            sb.append(ansArr[i]).append('\n');
        }
        System.out.print(sb);
    }

    static void buildMaps() {
        HashMap<Long, ArrayList<Integer>> tmpB = new HashMap<>();
        HashMap<Long, ArrayList<Integer>> tmpC = new HashMap<>();

        for (int i = 1; i <= N; i++) {
            tmpB.computeIfAbsent(B[i], k -> new ArrayList<>()).add(i);
            tmpC.computeIfAbsent(C[i], k -> new ArrayList<>()).add(i);
        }

        mapB = new LongMap(tmpB.size());
        for (Map.Entry<Long, ArrayList<Integer>> e : tmpB.entrySet()) {
            ArrayList<Integer> list = e.getValue();
            int[] arr = new int[list.size()];
            for (int j = 0; j < arr.length; j++) arr[j] = list.get(j);
            mapB.put(e.getKey(), arr);
        }

        mapC = new LongMap(tmpC.size());
        for (Map.Entry<Long, ArrayList<Integer>> e : tmpC.entrySet()) {
            ArrayList<Integer> list = e.getValue();
            int[] arr = new int[list.size()];
            for (int j = 0; j < arr.length; j++) arr[j] = list.get(j);
            mapC.put(e.getKey(), arr);
        }
    }

    // Count y in [a, b] with a > x and E(x, y) = K
    static long countRight(int x, int a, int b) {
        if (a > b) return 0;
        long res = 0;

        long targetB = B[x] + K;
        int hi1 = (int) Math.min(b, (long) x + K);
        if (hi1 >= a) {
            res += countValue(mapB, targetB, a, hi1);
        }

        long targetC = C[x] - K;
        int hi2 = (int) Math.min(b, (long) x + K - 1);
        if (hi2 >= a) {
            res += countValue(mapC, targetC, a, hi2);
        }

        return res;
    }

    // Count y in [a, b] with b < x and E(y, x) = K
    static long countLeft(int x, int a, int b) {
        if (a > b) return 0;
        long res = 0;

        long targetB = B[x] - K;
        int lo1 = (int) Math.max(a, (long) x - K);
        if (lo1 <= b) {
            res += countValue(mapB, targetB, lo1, b);
        }

        long targetC = C[x] + K;
        int lo2 = (int) Math.max(a, (long) x - K + 1);
        if (lo2 <= b) {
            res += countValue(mapC, targetC, lo2, b);
        }

        return res;
    }

    static long countValue(LongMap map, long val, int l, int r) {
        int[] arr = map.get(val);
        if (arr == null) return 0;
        int left = lowerBound(arr, l);
        int right = upperBound(arr, r);
        return right - left;
    }

    static int lowerBound(int[] arr, int l) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] < l) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    static int upperBound(int[] arr, int r) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] <= r) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    static class LongMap {
        long[] keys;
        int[][] vals;
        int mask;
        static final long EMPTY = Long.MIN_VALUE;

        LongMap(int expected) {
            int cap = 1;
            while (cap < expected * 2) cap <<= 1;
            keys = new long[cap];
            Arrays.fill(keys, EMPTY);
            vals = new int[cap][];
            mask = cap - 1;
        }

        void put(long key, int[] val) {
            int idx = hash(key) & mask;
            while (keys[idx] != EMPTY) {
                if (keys[idx] == key) {
                    vals[idx] = val;
                    return;
                }
                idx = (idx + 1) & mask;
            }
            keys[idx] = key;
            vals[idx] = val;
        }

        int[] get(long key) {
            int idx = hash(key) & mask;
            while (keys[idx] != EMPTY) {
                if (keys[idx] == key) return vals[idx];
                idx = (idx + 1) & mask;
            }
            return null;
        }

        static int hash(long x) {
            return (int) (x ^ (x >>> 32));
        }
    }

    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }
    }
}
